import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"42、【益】 震下巽上","description":"横渠易说 - 42、【益】 震下巽上","frontmatter":{"title":"42、【益】 震下巽上","description":"横渠易说 - 42、【益】 震下巽上"},"headers":[],"relativePath":"zh/classics/hengqu/044.md","filePath":"zh/classics/hengqu/044.md"}'),l={name:"zh/classics/hengqu/044.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_42、【益】-震下巽上" tabindex="-1">42、【益】 震下巽上 <a class="header-anchor" href="#_42、【益】-震下巽上" aria-label="Permalink to “42、【益】 震下巽上”">​</a></h1><h3 id="彖曰-益-损上益下-民说无疆。自上下下-其道大光。-利有攸往-中正有庆。-利涉大川-木道乃行。益动而巽-日进无疆。天施地生-其益无方。凡益之道-与时偕行。" tabindex="-1">彖曰：益，损上益下，民说无疆。自上下下，其道大光。“利有攸往”，中正有庆。“利涉大川”，木道乃行。益动而巽，日进无疆。天施地生，其益无方。凡益之道，与时偕行。 <a class="header-anchor" href="#彖曰-益-损上益下-民说无疆。自上下下-其道大光。-利有攸往-中正有庆。-利涉大川-木道乃行。益动而巽-日进无疆。天施地生-其益无方。凡益之道-与时偕行。" aria-label="Permalink to “彖曰：益，损上益下，民说无疆。自上下下，其道大光。“利有攸往”，中正有庆。“利涉大川”，木道乃行。益动而巽，日进无疆。天施地生，其益无方。凡益之道，与时偕行。”">​</a></h3><h3 id="象曰-风雷益-君子以见善则迁-有过则改。" tabindex="-1">象曰：风雷益，君子以见善则迁，有过则改。 <a class="header-anchor" href="#象曰-风雷益-君子以见善则迁-有过则改。" aria-label="Permalink to “象曰：风雷益，君子以见善则迁，有过则改。”">​</a></h3><p>上巽下动者，损上益下之道，木以动而巽，故“利涉大川”。否卦九四下而为初九，故曰“天施地生”，又曰“损上益下”，又曰“自上下下”。</p><h3 id="初九-利用为大作-元吉-无咎。-象曰-元吉无咎-下不厚事也。" tabindex="-1">初九，利用为大作，元吉，无咎。 象曰：“元吉无咎”，下不厚事也。 <a class="header-anchor" href="#初九-利用为大作-元吉-无咎。-象曰-元吉无咎-下不厚事也。" aria-label="Permalink to “初九，利用为大作，元吉，无咎。 象曰：“元吉无咎”，下不厚事也。”">​</a></h3><p>以刚阳之德施益于下，故利用大作。然必元吉乃无咎也。</p><h3 id="六二-或益之十朋之龟-弗克违-永贞吉。王用享于帝-吉。-象曰-或益之-自外来也。" tabindex="-1">六二，或益之十朋之龟，弗克违，永贞吉。王用享于帝，吉。 象曰：“或益之”，自外来也。 <a class="header-anchor" href="#六二-或益之十朋之龟-弗克违-永贞吉。王用享于帝-吉。-象曰-或益之-自外来也。" aria-label="Permalink to “六二，或益之十朋之龟，弗克违，永贞吉。王用享于帝，吉。 象曰：“或益之”，自外来也。”">​</a></h3><p>“或益之十朋之龟弗克违”，言损上益下之道，理不可易，人皆信之，虽十朋之龟亦不能违此道也。往见损，九五居中体柔，蒙上之益，修报于下，享帝之美，莫盛此焉。“或益之”，必有自外来而益之者也。</p><h3 id="六三-益之用凶事-无咎。有孚中行-告公用圭。-象曰-益用凶事-固有之也。" tabindex="-1">六三，益之用凶事，无咎。有孚中行，告公用圭。 象曰：益用凶事，固有之也。 <a class="header-anchor" href="#六三-益之用凶事-无咎。有孚中行-告公用圭。-象曰-益用凶事-固有之也。" aria-label="Permalink to “六三，益之用凶事，无咎。有孚中行，告公用圭。 象曰：益用凶事，固有之也。”">​</a></h3><p>中行者，不私于应，无所偏系也。用心不私，以拯凶难，虽非王者之佐，可以用之牧伯以为藩屏之臣矣。体躁居阳，上有刚应，持此施益，用拯凶难，乃其固能也，故无咎可必。然亦须执礼告上公而行，方合中道，其曰“告公”者，未足专进为王者之佐也。</p><h3 id="六四-中行告公从-利用为依迁国。-象曰-告公从-以益志也。" tabindex="-1">六四，中行告公从，利用为依迁国。 象曰：“告公从”，以益志也。 <a class="header-anchor" href="#六四-中行告公从-利用为依迁国。-象曰-告公从-以益志也。" aria-label="Permalink to “六四，中行告公从，利用为依迁国。 象曰：“告公从”，以益志也。”">​</a></h3><p>以阴居阴，体巽应卑，持此施益，可以为依迁之国。纯用卑柔，仍告上公见从，方可用事，无刚故也。不足告王，故曰“告公”。 本为初六，寄位于四，居阴体巽，所趋在下，以为依迁之国，人所容信，然必中行不私，然后可告必见从，盖上以益下为心也。</p><h3 id="九五-有孚惠心勿问-元吉。有孚惠我德。-象曰-有孚惠心-勿问之矣。-惠我德-大得志也。" tabindex="-1">九五，有孚惠心勿问，元吉。有孚惠我德。 象曰：“有孚惠心”，勿问之矣。“惠我德”，大得志也。 <a class="header-anchor" href="#九五-有孚惠心勿问-元吉。有孚惠我德。-象曰-有孚惠心-勿问之矣。-惠我德-大得志也。" aria-label="Permalink to “九五，有孚惠心勿问，元吉。有孚惠我德。 象曰：“有孚惠心”，勿问之矣。“惠我德”，大得志也。”">​</a></h3><h3 id="上九-莫益之-或击之-立心勿恒-凶。-象曰-莫益之-偏辞也。-或击之-自外来也。" tabindex="-1">上九，莫益之，或击之，立心勿恒，凶。 象曰：“莫益之”，偏辞也。“或击之”，自外来也。 <a class="header-anchor" href="#上九-莫益之-或击之-立心勿恒-凶。-象曰-莫益之-偏辞也。-或击之-自外来也。" aria-label="Permalink to “上九，莫益之，或击之，立心勿恒，凶。 象曰：“莫益之”，偏辞也。“或击之”，自外来也。”">​</a></h3><p>体刚质巽，志应在下，位亢于上，故立心勿恒。“或击之”，反“或益之”之义为文，故又云“自外来”也。 未尝损己而云“莫益之”，作易者因益卦而言尔。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
